package com.wildodds.gymtracker.data.parser.smart

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
/**
 * Locks the parsing behaviour of [SmartXlsxParser] for the classic Wild Odds template
 * (W1D1 sheet naming + Program Info). Fixture: src/test/resources/fixtures/smart_classic.xlsx
 * (regenerated by make_fixture.py in the same directory).
 *
 * Since phase 6 this path is an adapter over the shared engine rather than its own 773-line parser,
 * so this test now proves the FOLD was faithful: same name, same week count, same day, same
 * exercises, same order — with one deliberate change, noted at the assertion that covers it.
 */
class SmartXlsxParserTest {

  @Test
  fun parsesClassicTemplate() {
  val input = javaClass.getResourceAsStream("/fixtures/smart_classic.xlsx")
  assertNotNull("fixture workbook is missing from test resources", input)

  val result = input!!.use { SmartXlsxParser().parse(it) }

  // Program-level fields come from the Program Info sheet.
  assertEquals("Test Strength Program", result.name)
  assertEquals(4, result.weeksDetected)
  assertEquals(Layout.VERTICAL, result.layoutDetected)
  assertTrue(
  "expected the classic-template detection path, got: ${result.weekDetectionMethod}",
  result.weekDetectionMethod.contains("W1D1")
  )

  // One day (W1D1) with two exercises in order.
  assertEquals(1, result.weekTemplate.size)
  val day = result.weekTemplate.first()
  assertEquals("Push Day", day.name)
  assertEquals("Chest, Shoulders", day.muscleGroups)
  assertEquals(2, day.exercises.size)

  val bench = day.exercises[0]
  assertEquals("Bench Press", bench.nameOriginal)
  assertTrue(bench.name.isNotBlank())
  assertEquals(3, bench.sets)
  assertEquals("8-10", bench.reps)
  assertEquals(60f, bench.weight!!, 0.001f)
  // BEHAVIOUR CHANGE, deliberate. This fixture's column is headed "Weight" with no unit, and the
  // old parser defaulted such a column to KG. That default silently halved every import from an
  // American coach's sheet, and nothing downstream could detect it. The unit now stays UNKNOWN and
  // the review step asks — see docs/reader/04-gaps.md. A column headed "Weight (kg)" still reads
  // as KG, which is covered by the layout fixtures.
  assertEquals(WeightUnit.UNKNOWN, bench.weightUnit)
  assertEquals(0, bench.orderIndex)

  val ohp = day.exercises[1]
  assertEquals("Overhead Press", ohp.nameOriginal)
  assertEquals(3, ohp.sets)
  assertEquals("10", ohp.reps)
  assertEquals(40f, ohp.weight!!, 0.001f)
  assertEquals(1, ohp.orderIndex)
  }
}
